{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_by_id = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])
    from collections import Counter
    symbol_counts = Counter(n['symbol'] for n in nodes)
    removed_set = set()
    removed_order = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for node in sorted_nodes:
        nid = node['id']
        if nid in removed_set:
            continue
        if node['parent'] is None:
            continue
        if not node['removable']:
            continue
        has_retained_child = False
        for cid in children[nid]:
            if cid not in removed_set:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        sym = node['symbol']
        symbol_counts[sym] -= 1
        feasible = all(symbol_counts[rs] > 0 for rs in required_symbols)
        if feasible:
            removed_set.add(nid)
            removed_order.append(nid)
        else:
            symbol_counts[sym] += 1
    retained_ids = sorted([n['id'] for n in nodes if n['id'] not in removed_set])
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_ids}"}
